use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_exhausts_attempt_budget() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient(format!("failure {calls}")))
    });

    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
    assert_eq!(result, Err(RetryError::Transient("failure 3".into())));
}

#[test]
fn transient_failures_then_success_stop_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 4,
        max_delay_ms: 6,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![4, 6]);
}

#[test]
fn permanent_failure_is_returned_without_sleeping() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 4,
        max_delay_ms: 6,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

